#include "dmpf64/polynomial.h"
#include <stdlib.h>
#include <string.h>

void dmpf64_dense_free(dmpf64_dense_poly *p){ if(!p) return; free(p->c); p->c=NULL; p->len=0; }
int dmpf64_dense_new(dmpf64_dense_poly *p, size_t len){ p->c=(dmpf64_gf*)calloc(len,sizeof(dmpf64_gf)); p->len=p->c?len:0; return p->c?0:-1; }
int dmpf64_dense_random(dmpf64_dense_poly *p, size_t len, dmpf64_rng *rng){ if(dmpf64_dense_new(p,len)!=0)return -1; for(size_t i=0;i<len;i++)p->c[i]=dmpf64_rng_gf(rng); return 0; }
bool dmpf64_dense_eq_trim(const dmpf64_dense_poly *a, const dmpf64_dense_poly *b){ size_t m=a->len<b->len?a->len:b->len; for(size_t i=0;i<m;i++)if(a->c[i]!=b->c[i])return false; for(size_t i=m;i<a->len;i++)if(a->c[i])return false; for(size_t i=m;i<b->len;i++)if(b->c[i])return false; return true; }
int dmpf64_dense_add(dmpf64_dense_poly *out, const dmpf64_dense_poly *a, const dmpf64_dense_poly *b){ size_t n=a->len>b->len?a->len:b->len; if(dmpf64_dense_new(out,n)!=0)return -1; for(size_t i=0;i<n;i++){ dmpf64_gf av=i<a->len?a->c[i]:0, bv=i<b->len?b->c[i]:0; out->c[i]=av^bv;} return 0; }
int dmpf64_dense_mul_naive(dmpf64_dense_poly *out, const dmpf64_dense_poly *a, const dmpf64_dense_poly *b){ if(a->len==0||b->len==0) return dmpf64_dense_new(out,0); size_t n=a->len+b->len-1; if(dmpf64_dense_new(out,n)!=0)return -1; for(size_t i=0;i<a->len;i++) if(a->c[i]) for(size_t j=0;j<b->len;j++) if(b->c[j]) out->c[i+j]^=dmpf64_gf_mul(a->c[i],b->c[j]); return 0; }
dmpf64_gf dmpf64_dense_eval(const dmpf64_dense_poly *p, dmpf64_gf x){ dmpf64_gf pow=1, sum=0; for(size_t i=0;i<p->len;i++){ sum ^= dmpf64_gf_mul(p->c[i], pow); pow=dmpf64_gf_mul(pow,x);} return sum; }

void dmpf64_sparse_free(dmpf64_sparse_poly *p){ if(!p)return; free(p->terms); memset(p,0,sizeof(*p)); }
static int sparse_push(dmpf64_sparse_poly *p, size_t idx, dmpf64_gf c){ if(p->len==p->cap){ size_t nc=p->cap?p->cap*2:16; void *q=realloc(p->terms,nc*sizeof(*p->terms)); if(!q)return -1; p->terms=(dmpf64_sparse_term*)q; p->cap=nc;} p->terms[p->len++]=(dmpf64_sparse_term){idx,c}; return 0; }
static int term_cmp(const void*a,const void*b){const dmpf64_sparse_term*x=a,*y=b; return x->idx<y->idx?-1:x->idx>y->idx?1:0;}
static void sparse_sort_combine(dmpf64_sparse_poly *p){ if(p->len==0)return; qsort(p->terms,p->len,sizeof(*p->terms),term_cmp); size_t w=0; for(size_t r=0;r<p->len;r++){ if(p->terms[r].coeff==0)continue; if(w&&p->terms[w-1].idx==p->terms[r].idx) p->terms[w-1].coeff^=p->terms[r].coeff; else p->terms[w++]=p->terms[r]; if(w&&p->terms[w-1].coeff==0)w--; } p->len=w; }
int dmpf64_sparse_random(dmpf64_sparse_poly *p, size_t degree, size_t weight, dmpf64_rng *rng){ memset(p,0,sizeof(*p)); if(degree<=weight+1)return -1; while(p->len<weight){ size_t idx=(size_t)(dmpf64_rng_u64(rng)%degree); bool seen=false; for(size_t j=0;j<p->len;j++) if(p->terms[j].idx==idx){seen=true;break;} if(seen)continue; if(sparse_push(p,idx,dmpf64_rng_gf(rng))!=0){dmpf64_sparse_free(p);return -1;} } sparse_sort_combine(p); return 0; }
int dmpf64_sparse_random_regular(dmpf64_sparse_poly *p, size_t degree, size_t weight, dmpf64_rng *rng){ memset(p,0,sizeof(*p)); if(degree<=weight+1)return -1; size_t slice=dmpf64_ceil_div_size(degree,weight); for(size_t i=0;i<weight;i++){ if(i*slice>=degree)break; size_t idx=i*slice+(size_t)(dmpf64_rng_u64(rng)%slice); if(idx>=degree)idx=degree-1; if(sparse_push(p,idx,dmpf64_rng_gf(rng))!=0){dmpf64_sparse_free(p);return -1;} } sparse_sort_combine(p); return 0; }
int dmpf64_sparse_mul(dmpf64_sparse_poly *out, const dmpf64_sparse_poly *a, const dmpf64_sparse_poly *b){ memset(out,0,sizeof(*out)); for(size_t i=0;i<a->len;i++) for(size_t j=0;j<b->len;j++) if(sparse_push(out,a->terms[i].idx+b->terms[j].idx,dmpf64_gf_mul(a->terms[i].coeff,b->terms[j].coeff))!=0){dmpf64_sparse_free(out);return -1;} sparse_sort_combine(out); return 0; }
int dmpf64_sparse_to_dense(dmpf64_dense_poly *out, const dmpf64_sparse_poly *p){ size_t deg=0; for(size_t i=0;i<p->len;i++) if(p->terms[i].idx+1>deg) deg=p->terms[i].idx+1; if(dmpf64_dense_new(out,deg)!=0)return -1; for(size_t i=0;i<p->len;i++) out->c[p->terms[i].idx]^=p->terms[i].coeff; return 0; }

int dmpf64_share_polynomial(dmpf64_dpf_dmpf_key *k0, dmpf64_dpf_dmpf_key *k1, const dmpf64_sparse_poly *p, size_t points, size_t log_degree, dmpf64_rng *rng){
    if(points < p->len) return -1; size_t W=2, lower=1; size_t dpf_input_length=log_degree-lower; size_t max_points=(size_t)1<<dpf_input_length; if(points>max_points)points=max_points;
    dmpf64_kv *inputs=(dmpf64_kv*)calloc(points,sizeof(*inputs)); if(!inputs)return -1; size_t len=0;
    for(size_t i=0;i<p->len;i++){ size_t idx=p->terms[i].idx; uint64_t cur=(uint64_t)(idx>>lower); size_t internal=idx&1; dmpf64_node x=dmpf64_encode_index(cur,dpf_input_length); size_t j; for(j=0;j<len;j++) if(dmpf64_node_eq(inputs[j].x,x))break; if(j==len){inputs[len].x=x; inputs[len].y=dmpf64_gf2_zero(); len++;} inputs[j].y.v[internal]=p->terms[i].coeff; }
    while(len<points){ uint64_t idx=dmpf64_rng_u64(rng)%((uint64_t)1<<log_degree); dmpf64_node x=dmpf64_encode_index(idx>>lower,dpf_input_length); bool exists=false; for(size_t j=0;j<len;j++) if(dmpf64_node_eq(inputs[j].x,x)){exists=true;break;} if(exists)continue; inputs[len].x=x; inputs[len].y=dmpf64_gf2_zero(); len++; }
    int rc=dmpf64_dpf_dmpf_gen(k0,k1,dpf_input_length,inputs,len,rng); free(inputs); return rc;
}
int dmpf64_from_share(dmpf64_dense_poly *out, const dmpf64_dpf_dmpf_key *k){ dmpf64_gf2 *evals=NULL; size_t n=0; if(dmpf64_dpf_dmpf_eval_all(k,&evals,&n)!=0)return -1; if(dmpf64_dense_new(out,n*2)!=0){free(evals);return -1;} for(size_t i=0;i<n;i++){ out->c[2*i]=evals[i].v[0]; out->c[2*i+1]=evals[i].v[1]; } free(evals); return 0; }
int dmpf64_share_regular_polynomial_mul(dmpf64_dpf_dmpf_key **blocks0, dmpf64_dpf_dmpf_key **blocks1, size_t *block_count, size_t *block_size, const dmpf64_sparse_poly *p, size_t sqrt_points, size_t log_degree, dmpf64_rng *rng){
    size_t total_degree=(size_t)1<<log_degree; size_t t=sqrt_points; *block_size=dmpf64_ceil_div_size(total_degree/2,t); size_t bdp=dmpf64_next_pow2(*block_size); size_t log_sub=dmpf64_log2_pow2(bdp); *block_count=dmpf64_ceil_div_size(total_degree,*block_size);
    dmpf64_dpf_dmpf_key *b0=calloc(*block_count,sizeof(*b0)), *b1=calloc(*block_count,sizeof(*b1)); if(!b0||!b1){free(b0);free(b1);return -1;} size_t coeff_idx=0;
    for(size_t blk=0; blk<*block_count; blk++){ size_t min_deg=blk*(*block_size), max_deg=(blk+1)*(*block_size); size_t expected=2*(blk<(*block_count-blk)?blk:(*block_count-blk))+1; dmpf64_sparse_poly tmp={0}; while(coeff_idx<p->len && p->terms[coeff_idx].idx<max_deg){ sparse_push(&tmp,p->terms[coeff_idx].idx-min_deg,p->terms[coeff_idx].coeff); coeff_idx++; } for(size_t i=0; tmp.len<expected && i<*block_size; i++){ bool ex=false; for(size_t j=0;j<tmp.len;j++)if(tmp.terms[j].idx==i){ex=true;break;} if(!ex)sparse_push(&tmp,i,0); } sparse_sort_combine(&tmp); if(dmpf64_share_polynomial(&b0[blk],&b1[blk],&tmp,expected,log_sub,rng)!=0){dmpf64_sparse_free(&tmp);return -1;} dmpf64_sparse_free(&tmp); }
    *blocks0=b0; *blocks1=b1; return 0;
}
int dmpf64_from_share_regular_error(dmpf64_dense_poly *out, const dmpf64_dpf_dmpf_key *blocks, size_t block_count, size_t block_size, size_t output_degree){ if(dmpf64_dense_new(out,output_degree)!=0)return -1; for(size_t b=0;b<block_count;b++){ dmpf64_dense_poly p={0}; if(dmpf64_from_share(&p,&blocks[b])!=0)return -1; size_t start=b*block_size; for(size_t i=0;i<block_size && start+i<output_degree && i<p.len;i++) out->c[start+i]=p.c[i]; dmpf64_dense_free(&p);} return 0; }
